typedef unsigned int u_int;
typedef float rational_t;

void* operator new(unsigned int, const char*, int)
  __asm__("__nw__FUiUiPCci");

class color
{
public:
  float r, g, b, a;
};

enum light_flavor_t
{
  LIGHT_FLAVOR_NONE
};

class light_properties
{
protected:
  light_flavor_t flavor;
  color diffuse_color;
  color additive_color;
  rational_t near_range;
  rational_t cutoff_range;
  rational_t recip_cutoff_minus_near;
  u_int lightcat;
  unsigned flags;

  friend class light_source;
};

class entity
{
  char data[512];

public:
  void copy_instance_data(const entity&);
};

class light_source : public entity
{
  light_properties* properties;

public:
  const light_properties& get_properties() const { return *properties; }

protected:
  void copy_instance_data(const light_source&);
};

#define NEW new(__FILE__, 0)

void light_source::copy_instance_data(const light_source& b)
{
  entity::copy_instance_data(b);

  if (b.properties)
    if (!properties)
      properties = NEW light_properties(b.get_properties());
    else
      *properties = b.get_properties();
}
